using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;
public static class F1StructureVerify {
 static string Out=>Path.GetFullPath(Application.dataPath+"/../../../Docs/Review/2026-11-13_1F_RoofLiftWilderness/");
 static object Travel(CharacterController cc,GameObject player,string id,List<Vector3> route){cc.enabled=false;player.transform.position=route[0]+Vector3.up*(cc.height*.5f-cc.center.y+.025f);cc.enabled=true;Physics.SyncTransforms();int steps=0,segment=0;float remaining=0;bool pass=true;Vector3 target=route[0];foreach(var to in route.Skip(1)){target=to;segment++;int limit=Mathf.CeilToInt(Vector3.Distance(player.transform.position,to)/.07f)+95;for(int i=0;i<limit;i++){var d=to-player.transform.position;d.y=0;remaining=d.magnitude;if(remaining<.035f)break;cc.Move(d.normalized*Mathf.Min(.07f,remaining)+Vector3.down*.065f);steps++;}if(remaining>.12f){pass=false;break;}}for(int i=0;i<10;i++)cc.Move(Vector3.down*.04f);float bottom=player.transform.position.y+cc.center.y-cc.height*.5f;float err=bottom-target.y;if(Mathf.Abs(err)>.22f)pass=false;cc.enabled=false;return new{id,passed=pass,steps,segment,remaining,heightError=err,end=new[]{player.transform.position.x,bottom,player.transform.position.z}};}
 static float RoadZ(float x)=>-28-.035f*(-51-x)+Mathf.Sin((x+192)*.006f)*6*Mathf.SmoothStep(0,1,Mathf.InverseLerp(0,100,-x-192));
 public static object Walk(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying)throw new Exception("Saved edit required");var player=s.GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));var cc=player.GetComponent<CharacterController>();var results=new List<object>();
 try {cc.enabled=false;Physics.SyncTransforms();var entry=new List<Vector3>{new Vector3(40,0,-28),new Vector3(40.8f,0,-32.45f),new Vector3(44,0,-32.45f),new Vector3(44,0,-30.4f),new Vector3(44.96f,0,-30.32f)};results.Add(Travel(cc,player,"VB_lobby_to_landing",entry));entry.Reverse();results.Add(Travel(cc,player,"VB_landing_to_lobby",entry));
 var up=new List<Vector3>{new Vector3(43.04f,-18,-29.95f)};for(int flight=0;flight<10;flight++){int direction=flight%2==0?1:-1;float x=44+(direction==1?-.96f:.96f),z0=-1.62f*direction;up.Add(new Vector3(x,-18+flight*1.8f,-28+z0-direction*.32f));for(int i=0;i<12;i++)up.Add(new Vector3(x,-18+flight*1.8f+(i+1)*.15f,-28+z0+direction*(i+.5f)*.27f));float z=-28-z0+direction*.68f;up.Add(new Vector3(x,-18+(flight+1)*1.8f,z));if(flight<9)up.Add(new Vector3(44-(x-44),-18+(flight+1)*1.8f,z));}results.Add(Travel(cc,player,"VB_18m_up",up));up.Reverse();results.Add(Travel(cc,player,"VB_18m_down",up));
 var lift=new List<Vector3>{new Vector3(44,0,23.4f),new Vector3(44,.09f,25.9f),new Vector3(44,.075f,28.5f)};results.Add(Travel(cc,player,"Lift_enter",lift));lift.Reverse();results.Add(Travel(cc,player,"Lift_exit",lift));
 var road=new List<Vector3>();for(float x=-65;x>=-650;x-=2){float z=RoadZ(x);if(!Physics.Raycast(new Vector3(x,50,z),Vector3.down,out var hit,70,~0,QueryTriggerInteraction.Ignore))throw new Exception("No road ground at "+x);road.Add(new Vector3(x,hit.point.y,z));}results.Add(Travel(cc,player,"Wilderness_585m",road));road.Reverse();results.Add(Travel(cc,player,"Wilderness_return",road));
 }finally{EditorSceneManager.OpenScene(s.path);}var result=new{tested=results.Count,failed=results.Count(v=>!(bool)v.GetType().GetProperty("passed").GetValue(v)),results};File.WriteAllText(Out+"walk.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;}
 public static object Mechanical(){var s=SceneManager.GetActiveScene();var root=GameObject.Find("F1_VL_LiftAssembly").transform;var car=root.Find("Car");var cw=root.Find("Counterweight");var sh=root.Find("Sheave");var fixedRoot=root.Find("FixedShaft");var ropes=root.Find("Ropes");var list=new List<object>();foreach(float carY in new[]{0f,-9,-18}){float weightY=-17.2f-carY;float carRope=5.55f-(carY+3.79f),weightRope=5.55f-(weightY+2.96f);list.Add(new{carY,weightY,carRope,weightRope,totalStraight=carRope+weightRope,carBottom=carY-.075f,carTop=carY+3.79f,weightBottom=weightY,weightTop=weightY+2.96f});}
 var result=new{scene=s.path,assemblyPosition=new[]{root.position.x,root.position.y,root.position.z},separateRoots=new[]{car.name,cw.name,sh.name,fixedRoot.name,ropes.name},wheelAxis="local Z",doorSlideAxis="local X",attachedBehaviourTypes=root.GetComponentsInChildren<MonoBehaviour>(true).Select(c=>c.GetType().FullName).ToArray(),gameplayBehaviours=root.GetComponentsInChildren<MonoBehaviour>(true).Count(c=>!c.GetType().FullName.StartsWith("UnityEngine.Rendering.")),animations=root.GetComponentsInChildren<Animator>(true).Length,travel=list};File.WriteAllText(Out+"mechanical.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;}
}
